WITH cryo_heroes AS (
  SELECT hero_id FROM hero_power WHERE power_id = 19
),
shared_powers AS (
  SELECT DISTINCT power_id FROM hero_power WHERE hero_id IN (SELECT hero_id FROM cryo_heroes)
),
target_heroes AS (
  SELECT DISTINCT hero_id FROM hero_power WHERE power_id IN (SELECT power_id FROM shared_powers)
),
counts AS (
  SELECT hero_id, COUNT(*) AS n FROM hero_power WHERE hero_id IN (SELECT hero_id FROM target_heroes) GROUP BY hero_id
)
SELECT ROUND(AVG(n),1) AS avg_powers FROM counts
